                    <ProFormSwitch
                        label='\u53EF\u79FB\u9664'
                        checkedChildren='\u662F'
                        unCheckedChildren='\u5426'
                        fieldProps={{
                            checked: removable,
                            onChange: setRemovable,
                        }}
                    />
                    <ProFormSwitch
                        label='TweenOne \u52D5\u756B'
                        checkedChildren='\u662F'
                        unCheckedChildren='\u5426'
